const raw = $input.first().json || {};
const brand = (raw.brand || '').trim();
const category = (raw.category || '').trim();
const limit = Math.min(parseInt(raw.limit, 10) || 10, 20);
return [{ json: { brand, category, limit } }];

const rows = $input.all().map(i => i.json);
const input = $('Normalize Input').first().json;
if (!rows.length) {
  return [{ json: { found: false, message: `No hay productos activos para brand='${input.brand}' category='${input.category}'.`, query: input } }];
}
return [{ json: {
  found: true,
  count: rows.length,
  results: rows.map(r => ({
    sku: r.product_sku,
    title: r.title,
    brand: r.brand,
    category: r.category,
    price: r.price_amount ? `${r.price_amount} ${r.currency || 'USD'}` : 'consultar',
    stock: r.stock_status,
    image_url: r.image_url || null,
    promo: r.promo_text || null
  }))
} }];
